import { drizzle } from 'drizzle-orm/better-sqlite3';
import Database from 'better-sqlite3';
import * as schema from './schema';
import path from 'path';

// Use a local file for the SQLite database. 
// In a serverless environment like Vercel, /tmp is sometimes the only writable directory,
// but for a persistent local SQLite, we'll use the workspace root or a dedicated folder.
const dbPath = process.env.SQLITE_DB_PATH || path.join(process.cwd(), 'arkan.db');

const sqlite = new Database(dbPath);

// Enable WAL mode for better concurrency
sqlite.pragma('journal_mode = WAL');

export const db = drizzle(sqlite, { schema });

export type DbClient = typeof db;

import { injectable } from "tsyringe";
import { db } from "@/infrastructure/db";
import { users } from "@/infrastructure/db/schema";
import { IUserRepository } from "../../domain/repositories/IUserRepository";
import { UserProfile } from "../../domain/entities/User";
import { Result } from "@/lib/utils/result";
import { UserError } from "../../domain/errors/UserErrors";
import { eq, sql, desc, lt } from "drizzle-orm";

@injectable()
export class SQLiteUserRepository implements IUserRepository {
    async getById(id: string): Promise<Result<UserProfile, UserError>> {
        try {
            if (!id) return Result.fail(UserError.notFound());
            const user = await db.query.users.findFirst({
                where: eq(users.id, id),
            });
            if (!user) {
                return Result.fail(UserError.notFound());
            }
            return Result.ok(this.toDomain(user));
        } catch (error: any) {
            return Result.fail(UserError.internal(error.message));
        }
    }

    async save(user: UserProfile): Promise<Result<UserProfile, UserError>> {
        try {
            const data = this.toPersistence(user);
            await db.insert(users).values(data).onConflictDoUpdate({
                target: users.id,
                set: data,
            });
            return Result.ok(user);
        } catch (error: any) {
            return Result.fail(UserError.internal(error.message));
        }
    }

    async update(id: string, data: Partial<UserProfile>): Promise<Result<UserProfile, UserError>> {
        try {
            const persistenceData = this.toPersistencePartial(data);
            await db.update(users)
                .set({ ...persistenceData, updatedAt: new Date().toISOString() })
                .where(eq(users.id, id));
            return this.getById(id);
        } catch (error: any) {
            return Result.fail(UserError.internal(error.message));
        }
    }

    async delete(id: string): Promise<Result<void, UserError>> {
        try {
            await db.delete(users).where(eq(users.id, id));
            return Result.ok();
        } catch (error: any) {
            return Result.fail(UserError.internal(error.message));
        }
    }

    async deductCredits(id: string, amount: number): Promise<Result<number, UserError>> {
        try {
            return await db.transaction(async (tx) => {
                const user = await tx.query.users.findFirst({
                    where: eq(users.id, id),
                });

                if (!user) throw new Error("User not found");

                let currentCredits = user.credits ?? 0;
                const lastUpdate = user.lastDailyCreditUpdate ? new Date(user.lastDailyCreditUpdate).getTime() : 0;
                const twentyFourHours = 24 * 60 * 60 * 1000;

                const updates: any = {};

                if (Date.now() - lastUpdate > twentyFourHours) {
                    if (currentCredits < 10) {
                        currentCredits = 10;
                        updates.credits = currentCredits;
                    }
                    updates.lastDailyCreditUpdate = new Date().toISOString();
                }

                if (currentCredits < amount) {
                    return Result.fail(UserError.validation("Insufficient credits. Please purchase more credits to continue.")) as any;
                }

                const newBalance = currentCredits - amount;
                updates.credits = newBalance;
                updates.updatedAt = new Date().toISOString();

                await tx.update(users).set(updates).where(eq(users.id, id));
                return Result.ok(newBalance);
            });
        } catch (error: any) {
            return Result.fail(UserError.internal(error.message));
        }
    }

    async addCredits(id: string, amount: number): Promise<Result<void, UserError>> {
        try {
            await db.update(users)
                .set({ 
                    credits: sql`${users.credits} + ${amount}`,
                    updatedAt: new Date().toISOString()
                })
                .where(eq(users.id, id));
            return Result.ok();
        } catch (error: any) {
            return Result.fail(UserError.internal(error.message));
        }
    }

    async getPaginated({ limit, lastVisibleId }: { limit: number, lastVisibleId?: string }): Promise<Result<{ users: UserProfile[], hasNextPage: boolean, lastVisibleId: string | null }, UserError>> {
        try {
            let whereClause = undefined;
            if (lastVisibleId) {
                const lastUser = await db.query.users.findFirst({ where: eq(users.id, lastVisibleId) });
                if (lastUser) {
                    whereClause = lt(users.createdAt, lastUser.createdAt);
                }
            }

            const results = await db.query.users.findMany({
                where: whereClause,
                orderBy: [desc(users.createdAt)],
                limit: limit + 1,
            });

            const hasNextPage = results.length > limit;
            const usersList = results.slice(0, limit).map(this.toDomain);
            const newLastVisibleId = hasNextPage ? usersList[usersList.length - 1].id : null;

            return Result.ok({ users: usersList, hasNextPage, lastVisibleId: newLastVisibleId });
        } catch (error: any) {
            return Result.fail(UserError.internal(error.message));
        }
    }

    async getAdmins(): Promise<Result<UserProfile[], UserError>> {
        try {
            const results = await db.query.users.findMany({
                where: eq(users.role, 'admin'),
            });
            return Result.ok(results.map(this.toDomain));
        } catch (error: any) {
            return Result.fail(UserError.internal(error.message));
        }
    }

    private toDomain(user: any): UserProfile {
        return {
            ...user,
            apiKeys: user.apiKeys ? JSON.parse(user.apiKeys) : undefined,
            hasCompletedOnboarding: !!user.hasCompletedOnboarding,
        };
    }

    private toPersistence(user: UserProfile): any {
        return {
            ...user,
            apiKeys: user.apiKeys ? JSON.stringify(user.apiKeys) : null,
            hasCompletedOnboarding: user.hasCompletedOnboarding ? 1 : 0,
        };
    }

    private toPersistencePartial(user: Partial<UserProfile>): any {
        const data: any = { ...user };
        if (user.apiKeys) data.apiKeys = JSON.stringify(user.apiKeys);
        if (user.hasCompletedOnboarding !== undefined) data.hasCompletedOnboarding = user.hasCompletedOnboarding ? 1 : 0;
        return data;
    }
}

import { injectable } from "tsyringe";
import { db } from "@/infrastructure/db";
import { projects } from "@/infrastructure/db/schema";
import { IProjectRepository } from "../../domain/repositories/IProjectRepository";
import { Project, ProjectProperties } from "../../domain/entities/Project";
import { Result } from "@/lib/utils/result";
import { ProjectError } from "../../domain/errors/ProjectErrors";
import { eq, desc, and } from "drizzle-orm";
import { Telemetry } from "@/lib/utils/telemetry";

@injectable()
export class SQLiteProjectRepository implements IProjectRepository {
  async getById(id: string): Promise<Result<Project, ProjectError>> {
    try {
      const result = await db.query.projects.findFirst({
        where: eq(projects.id, id),
      });
      if (!result) {
        return Result.fail(ProjectError.notFound(`Project with id ${id} not found`));
      }
      return Result.ok(new Project(this.toDomain(result)));
    } catch (error: any) {
      Telemetry.logFailure('SQLiteProjectRepo:getById', error);
      return Result.fail(ProjectError.internal(error.message));
    }
  }

  async getByUserId(userId: string): Promise<Result<Project[], ProjectError>> {
    try {
      const results = await db.query.projects.findMany({
        where: eq(projects.authorId, userId),
        orderBy: [desc(projects.updated)],
      });

      const projectsList = results.map((result) => new Project(this.toDomain(result)));
      return Result.ok(projectsList);
    } catch (error: any) {
      Telemetry.logFailure('SQLiteProjectRepo:getByUserId', error);
      return Result.fail(ProjectError.internal(error.message));
    }
  }

  async save(project: ProjectProperties): Promise<Result<Project, ProjectError>> {
    try {
      const id = project.id || require('uuid').v4();
      const persistenceData = this.toPersistence({ ...project, id });

      await db.insert(projects).values(persistenceData).onConflictDoUpdate({
        target: projects.id,
        set: persistenceData,
      });

      return this.getById(id);
    } catch (error: any) {
      Telemetry.logFailure('SQLiteProjectRepo:save', error);
      return Result.fail(ProjectError.saveError(error.message));
    }
  }

  async delete(id: string): Promise<Result<void, ProjectError>> {
    try {
      await db.delete(projects).where(eq(projects.id, id));
      return Result.ok();
    } catch (error: any) {
      return Result.fail(ProjectError.deleteError(error.message));
    }
  }

  private toDomain(result: any): ProjectProperties {
    return {
      ...result,
      teamMembers: result.teamMembers ? JSON.parse(result.teamMembers) : undefined,
      content: result.content ? JSON.parse(result.content) : undefined,
      externalContext: result.externalContext ? JSON.parse(result.externalContext) : undefined,
      behaviors: result.behaviors ? JSON.parse(result.behaviors) : undefined,
      rules: result.rules ? JSON.parse(result.rules) : undefined,
      constraints: result.constraints ? JSON.parse(result.constraints) : undefined,
      meta: {
          author: result.authorId,
          version: result.version,
          created: result.created,
          updated: result.updated
      }
    };
  }

  private toPersistence(project: ProjectProperties): any {
    return {
      ...project,
      authorId: project.meta?.author || 'User',
      version: project.meta?.version || '1.0.0',
      created: project.meta?.created || new Date().toISOString(),
      updated: project.meta?.updated || new Date().toISOString(),
      teamMembers: project.teamMembers ? JSON.stringify(project.teamMembers) : null,
      content: project.content ? JSON.stringify(project.content) : null,
      externalContext: project.externalContext ? JSON.stringify(project.externalContext) : null,
      behaviors: project.behaviors ? JSON.stringify(project.behaviors) : null,
      rules: project.rules ? JSON.stringify(project.rules) : null,
      constraints: project.constraints ? JSON.stringify(project.constraints) : null,
    };
  }
}

import { injectable } from "tsyringe";
import { db } from "@/infrastructure/db";
import { agents, agentCategories } from "@/infrastructure/db/schema";
import { IAgentRepository } from "../../domain/repositories/IAgentRepository";
import { Agent, AgentProperties } from "../../domain/entities/Agent";
import { Result } from "@/lib/utils/result";
import { AiError } from "../../domain/errors/AiErrors";
import { eq, and } from "drizzle-orm";

@injectable()
export class SQLiteAgentRepository implements IAgentRepository {
    async getById(id: string): Promise<Result<Agent, AiError>> {
        try {
            const result = await db.query.agents.findFirst({
                where: eq(agents.id, id),
            });
            if (!result) {
                return Result.fail(AiError.notFound(`Agent with id ${id} not found`));
            }
            return Result.ok(new Agent(this.toDomain(result)));
        } catch (error: any) {
            return Result.fail(AiError.databaseError(error.message));
        }
    }

    async getAll(filters?: { category?: string, enabledOnly?: boolean }): Promise<Result<Agent[], AiError>> {
        try {
            let whereClause = undefined;
            if (filters?.category && filters?.enabledOnly) {
                whereClause = and(eq(agents.category, filters.category), eq(agents.isEnabled, true));
            } else if (filters?.category) {
                whereClause = eq(agents.category, filters.category);
            } else if (filters?.enabledOnly) {
                whereClause = eq(agents.isEnabled, true);
            }

            const results = await db.query.agents.findMany({
                where: whereClause,
                orderBy: (agents, { asc }) => [asc(agents.name)],
            });
            const agentsList = results.map(result => new Agent(this.toDomain(result)));
            return Result.ok(agentsList);
        } catch (error: any) {
            return Result.fail(AiError.databaseError(error.message));
        }
    }

    async save(id: string, data: any): Promise<Result<Agent, AiError>> {
        try {
            const now = new Date().toISOString();
            const existing = await db.query.agents.findFirst({ where: eq(agents.id, id) });
            const persistenceData = this.toPersistence({ ...data, id });

            if (!existing) {
                persistenceData.createdAt = now;
            }
            persistenceData.updatedAt = now;

            await db.insert(agents).values(persistenceData).onConflictDoUpdate({
                target: agents.id,
                set: persistenceData,
            });

            return this.getById(id);
        } catch (error: any) {
            return Result.fail(AiError.databaseError(error.message));
        }
    }

    async delete(id: string): Promise<Result<void, AiError>> {
        try {
            await db.delete(agents).where(eq(agents.id, id));
            return Result.ok();
        } catch (error: any) {
            return Result.fail(AiError.databaseError(error.message));
        }
    }

    async getCategories(): Promise<Result<any[], AiError>> {
        try {
            const results = await db.query.agentCategories.findMany({
                orderBy: (categories, { asc }) => [asc(categories.name)],
            });
            return Result.ok(results);
        } catch (error: any) {
            return Result.fail(AiError.databaseError(error.message));
        }
    }

    private toDomain(result: any): AgentProperties {
        return {
            ...result,
            guidelines: result.guidelines ? JSON.parse(result.guidelines) : [],
            isEnabled: !!result.isEnabled,
        };
    }

    private toPersistence(agent: any): any {
        return {
            ...agent,
            guidelines: agent.guidelines ? JSON.stringify(agent.guidelines) : null,
            isEnabled: agent.isEnabled ? 1 : 0,
        };
    }
}

import { injectable } from "tsyringe";
import { db } from "@/infrastructure/db";
import { transactions } from "@/infrastructure/db/schema";
import { ITransactionRepository } from "../../domain/repositories/ITransactionRepository";
import { TransactionProperties } from "../../domain/entities/Transaction";
import { Result } from "@/lib/utils/result";
import { BillingError } from "../../domain/errors/BillingErrors";
import { eq, desc, and, gte, lte, lt } from "drizzle-orm";
import { v4 as uuidv4 } from "uuid";

@injectable()
export class SQLiteTransactionRepository implements ITransactionRepository {
    async getById(id: string): Promise<Result<TransactionProperties, BillingError>> {
        try {
            const result = await db.query.transactions.findFirst({
                where: eq(transactions.id, id),
            });
            if (!result) {
                return Result.fail(BillingError.notFound(`Transaction with id ${id} not found`));
            }
            return Result.ok(result as TransactionProperties);
        } catch (error: any) {
            return Result.fail(BillingError.internal(error.message));
        }
    }

    async getAll(): Promise<Result<TransactionProperties[], BillingError>> {
        try {
            const results = await db.query.transactions.findMany({
                orderBy: [desc(transactions.createdAt)],
            });
            return Result.ok(results as TransactionProperties[]);
        } catch (error: any) {
            return Result.fail(BillingError.internal(error.message));
        }
    }

    async getByUserId(userId: string): Promise<Result<TransactionProperties[], BillingError>> {
        try {
            const results = await db.query.transactions.findMany({
                where: eq(transactions.userId, userId),
                orderBy: [desc(transactions.createdAt)],
            });
            return Result.ok(results as TransactionProperties[]);
        } catch (error: any) {
            return Result.fail(BillingError.internal(error.message));
        }
    }

    async save(data: Omit<TransactionProperties, 'id'>): Promise<Result<TransactionProperties, BillingError>> {
        try {
            const id = uuidv4();
            const dataToSave = {
                ...data,
                id,
                createdAt: data.createdAt || new Date().toISOString()
            };
            await db.insert(transactions).values(dataToSave as any);
            return Result.ok(dataToSave as TransactionProperties);
        } catch (error: any) {
            return Result.fail(BillingError.saveError(error.message));
        }
    }

    async update(id: string, data: Partial<TransactionProperties>): Promise<Result<TransactionProperties, BillingError>> {
        try {
            await db.update(transactions)
                .set(data)
                .where(eq(transactions.id, id));
            return this.getById(id);
        } catch (error: any) {
            return Result.fail(BillingError.updateError(error.message));
        }
    }

    async getPaginated(options: { status?: string, limit: number, lastVisibleId?: string }): Promise<Result<{ transactions: TransactionProperties[], hasNextPage: boolean, lastVisibleId: string | null }, BillingError>> {
        try {
            let whereClause = undefined;
            if (options.status) {
                whereClause = eq(transactions.status, options.status as any);
            }

            if (options.lastVisibleId) {
                const lastDoc = await db.query.transactions.findFirst({ where: eq(transactions.id, options.lastVisibleId) });
                if (lastDoc) {
                    const paginationFilter = lt(transactions.createdAt, lastDoc.createdAt);
                    whereClause = whereClause ? and(whereClause, paginationFilter) : paginationFilter;
                }
            }

            const results = await db.query.transactions.findMany({
                where: whereClause,
                orderBy: [desc(transactions.createdAt)],
                limit: options.limit + 1,
            });

            const hasNextPage = results.length > options.limit;
            const items = results.slice(0, options.limit) as TransactionProperties[];
            const lastId = hasNextPage ? items[items.length - 1].id : null;

            return Result.ok({ transactions: items, hasNextPage, lastVisibleId: lastId });
        } catch (error: any) {
            return Result.fail(BillingError.internal(error.message));
        }
    }

    async getByDateRange(startDate: string, endDate: string): Promise<Result<TransactionProperties[], BillingError>> {
        try {
            const results = await db.query.transactions.findMany({
                where: and(
                    gte(transactions.createdAt, startDate),
                    lte(transactions.createdAt, endDate)
                ),
                orderBy: [desc(transactions.createdAt)],
            });
            return Result.ok(results as TransactionProperties[]);
        } catch (error: any) {
            return Result.fail(BillingError.internal(error.message));
        }
    }
}

