import { injectable } from "tsyringe";
import { db } from "@/infrastructure/db";
import { templates } from "@/infrastructure/db/schema";
import { ITemplateRepository } from "../../domain/repositories/ITemplateRepository";
import { Result } from "@/lib/utils/result";
import { TemplateError } from "../../domain/errors/TemplateErrors";
import { eq, and, desc } from "drizzle-orm";

@injectable()
export class SQLiteTemplateRepository implements ITemplateRepository {
    async getById(id: string, type: 'docx' | 'pptx' | 'report'): Promise<Result<any, TemplateError>> {
        try {
            const result = await db.query.templates.findFirst({
                where: and(eq(templates.id, id), eq(templates.type, type)),
            });
            if (!result) {
                return Result.fail(TemplateError.notFound(`Template ${id} of type ${type} not found`));
            }
            return Result.ok(this.toDomain(result));
        } catch (error: any) {
            return Result.fail(TemplateError.internal(error.message));
        }
    }

    async getAll(type: 'docx' | 'pptx' | 'report'): Promise<Result<any[], TemplateError>> {
        try {
            const results = await db.query.templates.findMany({
                where: eq(templates.type, type),
                orderBy: [desc(templates.createdAt)],
            });
            return Result.ok(results.map(this.toDomain));
        } catch (error: any) {
            return Result.fail(TemplateError.internal(error.message));
        }
    }

    async save(template: any, type: 'docx' | 'pptx' | 'report'): Promise<Result<any, TemplateError>> {
        try {
            const now = new Date().toISOString();
            const persistenceData = this.toPersistence({ ...template, type });

            const existing = await db.query.templates.findFirst({
                where: and(eq(templates.id, template.id), eq(templates.type, type)),
            });

            if (!existing) {
                persistenceData.createdAt = now;
            }
            persistenceData.updatedAt = now;

            await db.insert(templates).values(persistenceData).onConflictDoUpdate({
                target: templates.id,
                set: persistenceData,
            });
            return Result.ok(template);
        } catch (error: any) {
            return Result.fail(TemplateError.saveError(error.message));
        }
    }

    async delete(id: string, type: 'docx' | 'pptx' | 'report'): Promise<Result<void, TemplateError>> {
        try {
            await db.delete(templates).where(and(eq(templates.id, id), eq(templates.type, type)));
            return Result.ok();
        } catch (error: any) {
            return Result.fail(TemplateError.deleteError(error.message));
        }
    }

    private toDomain(result: any): any {
        return {
            ...result,
            isDefault: !!result.isDefault,
            content: result.content ? JSON.parse(result.content) : undefined,
        };
    }

    private toPersistence(template: any): any {
        return {
            ...template,
            isDefault: template.isDefault ? 1 : 0,
            content: template.content ? JSON.stringify(template.content) : null,
        };
    }
}

import { injectable } from "tsyringe";
import { db } from "@/infrastructure/db";
import { generationLogs, agents, users } from "@/infrastructure/db/schema";
import { IGenerationLogRepository, GenerationLog } from "../../domain/repositories/IGenerationLogRepository";
import { Result } from "@/lib/utils/result";
import { AiError } from "../../domain/errors/AiErrors";
import { eq, desc, and, lt } from "drizzle-orm";

@injectable()
export class SQLiteGenerationLogRepository implements IGenerationLogRepository {
    async log(entry: GenerationLog): Promise<Result<void, AiError>> {
        try {
            await db.insert(generationLogs).values({
                agentId: entry.agentId,
                userId: entry.userId,
                input: JSON.stringify(entry.input),
                output: JSON.stringify(entry.output),
                creditCost: entry.creditCost,
                timestamp: entry.timestamp || new Date().toISOString(),
            });
            return Result.ok();
        } catch (error: any) {
            return Result.fail(AiError.databaseError(error.message));
        }
    }

    async getByUserId(userId: string): Promise<Result<GenerationLog[], AiError>> {
        try {
            const results = await db.query.generationLogs.findMany({
                where: eq(generationLogs.userId, userId),
                orderBy: [desc(generationLogs.timestamp)],
            });
            return Result.ok(results.map(this.toDomain));
        } catch (error: any) {
            return Result.fail(AiError.databaseError(error.message));
        }
    }

    async getPaginated(options: { limit: number, agentId?: string, userId?: string, lastVisibleId?: string }): Promise<Result<{ logs: any[], hasNextPage: boolean, lastVisibleId: string | null }, AiError>> {
        try {
            let whereClause = undefined;
            if (options.agentId && options.userId) {
                whereClause = and(eq(generationLogs.agentId, options.agentId), eq(generationLogs.userId, options.userId));
            } else if (options.agentId) {
                whereClause = eq(generationLogs.agentId, options.agentId);
            } else if (options.userId) {
                whereClause = eq(generationLogs.userId, options.userId);
            }

            if (options.lastVisibleId) {
                const lastLog = await db.query.generationLogs.findFirst({ where: eq(generationLogs.id, parseInt(options.lastVisibleId)) });
                if (lastLog) {
                    const paginationFilter = lt(generationLogs.timestamp, lastLog.timestamp);
                    whereClause = whereClause ? and(whereClause, paginationFilter) : paginationFilter;
                }
            }

            const results = await db.query.generationLogs.findMany({
                where: whereClause,
                orderBy: [desc(generationLogs.timestamp)],
                limit: options.limit + 1,
            });

            const hasNextPage = results.length > options.limit;
            const items = results.slice(0, options.limit).map(this.toDomain);
            const lastId = hasNextPage ? items[items.length - 1].id?.toString() || null : null;

            return Result.ok({ logs: items, hasNextPage, lastVisibleId: lastId });
        } catch (error: any) {
            return Result.fail(AiError.databaseError(error.message));
        }
    }

    private toDomain(result: any): any {
        return {
            ...result,
            input: JSON.parse(result.input),
            output: JSON.parse(result.output),
        };
    }
}

import { injectable } from "tsyringe";
import { db } from "@/infrastructure/db";
import { features } from "@/infrastructure/db/schema";
import { IFeatureRepository } from "../../domain/repositories/IFeatureRepository";
import { Feature } from "../../domain/entities/Feature";
import { eq } from "drizzle-orm";

@injectable()
export class SQLiteFeatureRepository implements IFeatureRepository {
    async getAll(): Promise<Feature[]> {
        const results = await db.query.features.findMany();
        return results.map(this.toDomain);
    }

    async getById(id: string): Promise<Feature | null> {
        const result = await db.query.features.findFirst({
            where: eq(features.id, id),
        });
        return result ? this.toDomain(result) : null;
    }

    async update(id: string, data: Partial<Feature>): Promise<Feature> {
        const updatedAt = new Date().toISOString();
        const persistenceData = this.toPersistencePartial({ ...data, updatedAt });
        await db.update(features)
            .set(persistenceData)
            .where(eq(features.id, id));

        const updated = await this.getById(id);
        if (!updated) throw new Error(`Feature ${id} not found after update`);
        return updated;
    }

    private toDomain(result: any): Feature {
        return {
            ...result,
            isEnabled: !!result.isEnabled,
        };
    }

    private toPersistencePartial(data: Partial<Feature>): any {
        const persistence: any = { ...data };
        if (data.isEnabled !== undefined) {
            persistence.isEnabled = data.isEnabled ? 1 : 0;
        }
        return persistence;
    }
}

import { injectable } from "tsyringe";
import { db } from "@/infrastructure/db";
import { settings } from "@/infrastructure/db/schema";
import { ISettingsRepository } from "../../domain/repositories/ISettingsRepository";
import { AppSettings } from "../../domain/entities/Settings";
import { eq } from "drizzle-orm";

@injectable()
export class SQLiteSettingsRepository implements ISettingsRepository {
    private readonly SETTINGS_KEY = 'defaults';

    async get(): Promise<AppSettings> {
        const result = await db.query.settings.findFirst({
            where: eq(settings.key, this.SETTINGS_KEY),
        });

        if (!result) {
            // Default settings if not found
            return {
                newUserCredits: 10,
                paymentMethods: [],
            };
        }

        return JSON.parse(result.value) as AppSettings;
    }

    async update(data: AppSettings): Promise<AppSettings> {
        const value = JSON.stringify(data);

        await db.insert(settings)
            .values({ key: this.SETTINGS_KEY, value })
            .onConflictDoUpdate({
                target: settings.key,
                set: { value },
            });

        return data;
    }
}

import { injectable } from "tsyringe";
import { db } from "@/infrastructure/db";
import { users, generationLogs, transactions, agents } from "@/infrastructure/db/schema";
import { IAdminStatsRepository, DashboardStats } from "../../domain/repositories/IAdminStatsRepository";
import { count, eq, sql, desc } from "drizzle-orm";

@injectable()
export class SQLiteAdminStatsRepository implements IAdminStatsRepository {
    async getDashboardStats(): Promise<DashboardStats> {
        const [userCountResult] = await db.select({ count: count() }).from(users);
        const [genLogCountResult] = await db.select({ count: count() }).from(generationLogs);
        const [pendingPaymentsResult] = await db.select({ count: count() })
            .from(transactions)
            .where(eq(transactions.status, 'pending'));

        const agentUsage = await db.select({
            agentId: generationLogs.agentId,
            name: agents.name,
            count: count(generationLogs.id),
        })
        .from(generationLogs)
        .leftJoin(agents, eq(generationLogs.agentId, agents.id))
        .groupBy(generationLogs.agentId)
        .orderBy(desc(count(generationLogs.id)))
        .limit(10);

        // Fetch some recent activity
        const recentGenLogs = await db.query.generationLogs.findMany({
            orderBy: [desc(generationLogs.timestamp)],
            limit: 5,
        });

        const recentTransactions = await db.query.transactions.findMany({
            orderBy: [desc(transactions.createdAt)],
            limit: 5,
        });

        const recentActivity = [
            ...recentGenLogs.map(log => ({
                id: `log-${log.id}`,
                type: 'generation',
                userId: log.userId,
                timestamp: log.timestamp,
                details: `Generated content with agent ${log.agentId}`
            })),
            ...recentTransactions.map(tx => ({
                id: `tx-${tx.id}`,
                type: 'transaction',
                userId: tx.userId,
                timestamp: tx.createdAt,
                details: `Transaction ${tx.id} - ${tx.status}`
            }))
        ].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()).slice(0, 10);

        return {
            totalUsers: userCountResult.count,
            totalGenerations: genLogCountResult.count,
            pendingPayments: pendingPaymentsResult.count,
            agentUsageChartData: agentUsage.map(u => ({
                name: u.name || 'Unknown Agent',
                agentId: u.agentId,
                count: u.count,
            })),
            recentActivity,
        };
    }
}

import { injectable } from "tsyringe";
import { db } from "@/infrastructure/db";
import { indexedDocuments } from "@/infrastructure/db/schema";
import { IIndexedDocumentRepository, IndexedDocumentRecord } from "../../domain/repositories/IIndexedDocumentRepository";
import { Result } from "@/lib/utils/result";
import { RagError } from "../../domain/errors/RagErrors";
import { eq, desc, count, sql, like, or } from "drizzle-orm";
import { v4 as uuidv4 } from "uuid";

@injectable()
export class SQLiteIndexedDocumentRepository implements IIndexedDocumentRepository {
    async record(data: Omit<IndexedDocumentRecord, 'id' | 'timestamp' | 'indexedAt' | 'status'>): Promise<Result<string, RagError>> {
        try {
            const id = uuidv4();
            const now = Date.now();
            const indexedAt = new Date().toISOString();

            await db.insert(indexedDocuments).values({
                ...data,
                id,
                timestamp: now,
                indexedAt,
                status: 'indexed',
            } as any);

            return Result.ok(id);
        } catch (error: any) {
            return Result.fail(RagError.internal(error.message));
        }
    }

    async recordFailed(data: Omit<IndexedDocumentRecord, 'id' | 'timestamp' | 'indexedAt' | 'status' | 'chunksCount'>): Promise<Result<string, RagError>> {
        try {
            const id = uuidv4();
            const now = Date.now();
            const indexedAt = new Date().toISOString();

            await db.insert(indexedDocuments).values({
                ...data,
                id,
                timestamp: now,
                indexedAt,
                chunksCount: 0,
                status: 'failed',
            } as any);

            return Result.ok(id);
        } catch (error: any) {
            return Result.fail(RagError.internal(error.message));
        }
    }

    async getAll(limit: number = 50): Promise<Result<IndexedDocumentRecord[], RagError>> {
        try {
            const results = await db.query.indexedDocuments.findMany({
                orderBy: [desc(indexedDocuments.indexedAt)],
                limit,
            });
            return Result.ok(results.map(this.toDomain));
        } catch (error: any) {
            return Result.fail(RagError.internal(error.message));
        }
    }

    async getByProjectId(projectId: string): Promise<Result<IndexedDocumentRecord[], RagError>> {
        try {
            const results = await db.query.indexedDocuments.findMany({
                where: eq(indexedDocuments.projectId, projectId),
                orderBy: [desc(indexedDocuments.indexedAt)],
            });
            return Result.ok(results.map(this.toDomain));
        } catch (error: any) {
            return Result.fail(RagError.internal(error.message));
        }
    }

    async getByUserId(userId: string): Promise<Result<IndexedDocumentRecord[], RagError>> {
        try {
            const results = await db.query.indexedDocuments.findMany({
                where: eq(indexedDocuments.userId, userId),
                orderBy: [desc(indexedDocuments.indexedAt)],
            });
            return Result.ok(results.map(this.toDomain));
        } catch (error: any) {
            return Result.fail(RagError.internal(error.message));
        }
    }

    async deleteByProjectId(projectId: string): Promise<Result<void, RagError>> {
        try {
            await db.update(indexedDocuments)
                .set({ status: 'deleted' })
                .where(eq(indexedDocuments.projectId, projectId));
            return Result.ok();
        } catch (error: any) {
            return Result.fail(RagError.internal(error.message));
        }
    }

    async deleteBySourceFile(sourceFile: string): Promise<Result<void, RagError>> {
        try {
            await db.update(indexedDocuments)
                .set({ status: 'deleted' })
                .where(eq(indexedDocuments.sourceFile, sourceFile));
            return Result.ok();
        } catch (error: any) {
            return Result.fail(RagError.internal(error.message));
        }
    }

    async search(query: string): Promise<Result<IndexedDocumentRecord[], RagError>> {
        try {
            const results = await db.query.indexedDocuments.findMany({
                where: or(
                    like(indexedDocuments.sourceFile, `%${query}%`),
                    like(indexedDocuments.errorMessage, `%${query}%`)
                ),
                orderBy: [desc(indexedDocuments.indexedAt)],
            });
            return Result.ok(results.map(this.toDomain));
        } catch (error: any) {
            return Result.fail(RagError.internal(error.message));
        }
    }

    async getStats(): Promise<Result<{
        totalDocuments: number;
        totalChunks: number;
        projectCount: number;
        recentUploads: number;
    }, RagError>> {
        try {
            const [totalDocs] = await db.select({ value: count() }).from(indexedDocuments).where(eq(indexedDocuments.status, 'indexed'));
            const [totalChunks] = await db.select({ value: sql`SUM(${indexedDocuments.chunksCount})` }).from(indexedDocuments).where(eq(indexedDocuments.status, 'indexed'));
            const [projectCount] = await db.select({ value: sql`COUNT(DISTINCT ${indexedDocuments.projectId})` }).from(indexedDocuments).where(eq(indexedDocuments.status, 'indexed'));

            const oneDayAgo = Date.now() - 24 * 60 * 60 * 1000;
            const [recentUploads] = await db.select({ value: count() }).from(indexedDocuments).where(and(eq(indexedDocuments.status, 'indexed'), gte(indexedDocuments.timestamp, oneDayAgo)));

            return Result.ok({
                totalDocuments: Number(totalDocs.value),
                totalChunks: Number(totalChunks.value || 0),
                projectCount: Number(projectCount.value || 0),
                recentUploads: Number(recentUploads.value),
            });
        } catch (error: any) {
            return Result.fail(RagError.internal(error.message));
        }
    }

    private toDomain(result: any): IndexedDocumentRecord {
        return {
            ...result,
            indexedAt: result.indexedAt, // Drizzle returns strings/dates, Repository interface expected Timestamp (from firebase-admin)
        } as any;
    }
}

// Internal helper for gte since it's not imported above
function gte(column: any, value: any) {
    return sql`${column} >= ${value}`;
}

