'use client';

import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { Checkbox } from '@/components/ui/checkbox';
import { useLogin } from '@/hooks/auth/use-auth-mutations';
import { zodResolver } from '@hookform/resolvers/zod';
import { AlertCircle, Loader2 } from 'lucide-react';
import { generateFingerprint } from '@/lib/utils/security/fingerprint';
import Link from 'next/link';
import { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { z } from 'zod';
import { apiService } from '@/infrastructure/api/ApiService';
import { handleErrorUtility } from '@/lib/utils/errorUtils';

const formSchema = z.object({ 
  email: z.string().email({ message: 'Please enter a valid email address.' }), 
  password: z.string().min(1, { message: 'Password is required.' }),
  rememberMe: z.boolean().default(false)
});

export default function LoginForm() {
  const loginMutation = useLogin();
  const form = useForm<z.infer<typeof formSchema>>({ 
    resolver: zodResolver(formSchema), 
    defaultValues: { email: '', password: '', rememberMe: false } 
  });

  useEffect(() => { 
    const errorData = loginMutation.error as any; 
    if (errorData?.message) { 
      form.setError('root.serverError', { type: 'manual', message: errorData.message }); 
    } 
  }, [loginMutation.error, form]);

  async function onSubmit(values: z.infer<typeof formSchema>) { 
    form.clearErrors('root.serverError'); 

    // Capture Fingerprint
    const { hash, data } = await generateFingerprint();

    loginMutation.mutate({
        ...values,
        fingerprint: hash,
        fingerprintData: data
    } as any); 
  }

  const handleGuestLogin = async () => { 
    try { 
      await apiService<undefined, unknown>({ endpoint: '/api/auth/guest', method: 'POST' }); 
      window.location.href = '/builder'; 
    } catch (error) { 
      handleErrorUtility(error, 'Guest Login Failed'); 
    } 
  };

  const isPending = loginMutation.isPending;
  const formLevelError = form.formState.errors.root?.serverError;

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="grid gap-4">
        {formLevelError && (
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertTitle>Login Error</AlertTitle>
            <AlertDescription>{formLevelError.message}</AlertDescription>
          </Alert>
        )}
        <FormField 
          control={form.control} 
          name="email" 
          render={({ field }) => (
            <FormItem>
              <FormLabel>Email</FormLabel>
              <FormControl>
                <Input placeholder="name@example.com" {...field} disabled={isPending} />
              </FormControl>
              <FormMessage />
            </FormItem>
          )} 
        />
        <FormField 
          control={form.control} 
          name="password" 
          render={({ field }) => (
            <FormItem>
              <div className="flex items-center">
                <FormLabel>Password</FormLabel>
                <Link href="/forgot-password" className={`ms-auto inline-block text-sm underline ${isPending ? 'pointer-events-none opacity-50' : ''}`}>
                  Forgot your password?
                </Link>
              </div>
              <FormControl>
                <Input type="password" placeholder="••••••••" {...field} disabled={isPending} />
              </FormControl>
              <FormMessage />
            </FormItem>
          )} 
        />
        <FormField
          control={form.control}
          name="rememberMe"
          render={({ field }) => (
            <FormItem className="flex flex-row items-center space-x-3 space-y-0 rounded-md py-2">
              <FormControl>
                <Checkbox
                  checked={field.value}
                  onCheckedChange={field.onChange}
                  disabled={isPending}
                />
              </FormControl>
              <div className="space-y-1 leading-none">
                <FormLabel className="text-sm font-normal">
                  Remember me
                </FormLabel>
              </div>
            </FormItem>
          )}
        />
        <Button type="submit" className="w-full" disabled={isPending}>
          {loginMutation.isPending && <Loader2 className="me-2 h-4 w-4 animate-spin" />} 
          Login
        </Button>

        <div className="relative my-2">
          <div className="absolute inset-0 flex items-center">
            <span className="w-full border-t" />
          </div>
          <div className="relative flex justify-center text-xs uppercase">
            <span className="bg-background px-2 text-muted-foreground">Or continue without an account</span>
          </div>
        </div>

        <Button variant="secondary" className="w-full" type="button" onClick={handleGuestLogin} disabled={isPending}>
          Continue as Guest
        </Button>

        <div className="mt-4 text-center text-sm">
          Don&apos;t have an account?{" "}
          <Link href="/signup" className="underline">
            Sign up
          </Link>
        </div>
      </form>
    </Form>
  );
}

'use client';

import { Button } from '@/components/ui/button';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { useLocalization } from '@/context/LocalizationContext';
import { useSignup } from '@/hooks/auth/use-auth-mutations';
import { zodResolver } from '@hookform/resolvers/zod';
import { Loader2 } from 'lucide-react';
import { generateFingerprint } from '@/lib/utils/security/fingerprint';
import Link from 'next/link';
import { useForm } from 'react-hook-form';
import { z } from 'zod';

const formSchema = z.object({
  name: z.string().min(2, { message: 'Name must be at least 2 characters.' }),
  email: z.string().email({ message: 'Please enter a valid email address.' }),
  password: z.string().min(6, { message: 'Password must be at least 6 characters.' }),
});

export type SignupCredentials = z.infer<typeof formSchema>;

export default function SignupForm() {
  const { t } = useLocalization();
  const signupMutation = useSignup();

  const form = useForm<SignupCredentials>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      name: '',
      email: '',
      password: '',
    },
  });

  async function onSubmit(values: SignupCredentials) {
    // Capture Fingerprint
    const { hash, data } = await generateFingerprint();

    signupMutation.mutate({
        ...values,
        fingerprint: hash,
        fingerprintData: data
    } as any);
  }

  const isPending = signupMutation.isPending;

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="grid gap-4">
        <FormField
          control={form.control}
          name="name"
          render={({ field }) => (
            <FormItem>
              <FormLabel>{t('signup.nameLabel')}</FormLabel>
              <FormControl>
                <Input placeholder={t('signup.namePlaceholder')} {...field} disabled={isPending} />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
        <FormField
          control={form.control}
          name="email"
          render={({ field }) => (
            <FormItem>
              <FormLabel>{t('signup.emailLabel')}</FormLabel>
              <FormControl>
                <Input placeholder="name@example.com" {...field} disabled={isPending} />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
        <FormField
          control={form.control}
          name="password"
          render={({ field }) => (
            <FormItem>
              <FormLabel>{t('signup.passwordLabel')}</FormLabel>
              <FormControl>
                <Input type="password" placeholder="••••••••" {...field} disabled={isPending} />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
        <Button type="submit" className="w-full" disabled={isPending}>
          {signupMutation.isPending && <Loader2 className="me-2 h-4 w-4 animate-spin" />}
          {t('signup.submitButton')}
        </Button>

        <div className="mt-4 text-center text-sm">
          {t('signup.loginPrompt')}{" "}
          <Link href="/login" className="underline">
            {t('signup.loginLink')}
          </Link>
        </div>
      </form>
    </Form>
  );
}

