        queryKey: ['user-fingerprints', userId],
        queryFn: async () => {
            const client = container.resolve(UserApiClient);
            const result = await client.fetchUserFingerprints(userId);
            if (result.isFailure) throw result.error;
            return result.getValue();
        }
