import { injectable } from "tsyringe";
import { db } from "@/infrastructure/db";
import { securityAuditLogs, notifications, loginHistory } from "@/infrastructure/db/schema";
import { Result } from "@/lib/utils/result";
import { UserError } from "../../domain/errors/UserErrors";
import { lt } from "drizzle-orm";

@injectable()
export class CleanupOldRecordsUseCase {
    /**
     * Deletes records older than the specified number of days.
     * Default is 90 days.
     */
    async execute(days: number = 90): Promise<Result<{ deletedLogs: number, deletedNotifications: number }, UserError>> {
        try {
            const cutoffDate = new Date();
            cutoffDate.setDate(cutoffDate.getDate() - days);
            const cutoffStr = cutoffDate.toISOString();

            // 1. Cleanup Audit Logs
            const logsResult = await db.delete(securityAuditLogs)
                .where(lt(securityAuditLogs.timestamp, cutoffStr));

            // 2. Cleanup Notifications (only read ones or all?)
            // For now, let's clean up all notifications older than cutoff
            const notificationsResult = await db.delete(notifications)
                .where(lt(notifications.createdAt, cutoffStr));

            // 3. Cleanup Login History
            await db.delete(loginHistory)
                .where(lt(loginHistory.timestamp, cutoffStr));

            return Result.ok({
                deletedLogs: logsResult.changes,
                deletedNotifications: notificationsResult.changes
            });
        } catch (error: any) {
            return Result.fail(UserError.internal(error.message));
        }
    }
}

import { injectable } from "tsyringe";
import { authenticator } from "otplib";
import QRCode from "qrcode";
import { Result } from "@/lib/utils/result";

@injectable()
export class TwoFactorAuthService {
    /**
     * Generates a new TOTP secret.
     */
    generateSecret(): string {
        return authenticator.generateSecret();
    }

    /**
     * Generates a setup QR code URL for the user.
     */
    async generateQrCode(email: string, secret: string): Promise<string> {
        const otpauth = authenticator.keyuri(email, 'Arkan', secret);
        return QRCode.toDataURL(otpauth);
    }

    /**
     * Verifies a TOTP token against a secret.
     */
    verifyToken(token: string, secret: string): boolean {
        return authenticator.verify({ token, secret });
    }
}

import { injectable } from "tsyringe";
import { db } from "@/infrastructure/db";
import { users } from "@/infrastructure/db/schema";
import { Result } from "@/lib/utils/result";
import { UserError } from "../../domain/errors/UserErrors";
import { TwoFactorAuthService } from "../../infrastructure/services/TwoFactorAuthService";
import { eq } from "drizzle-orm";

@injectable()
export class Setup2FAUseCase {
    constructor(
        private tfaService: TwoFactorAuthService
    ) {}

    async execute(userId: string): Promise<Result<{ secret: string, qrCode: string }, UserError>> {
        try {
            const user = await db.query.users.findFirst({ where: eq(users.id, userId) });
            if (!user) return Result.fail(UserError.notFound());

            const secret = this.tfaService.generateSecret();
            const qrCode = await this.tfaService.generateQrCode(user.email, secret);

            // Store secret but don't enable yet
            await db.update(users)
                .set({ twoFactorSecret: secret, updatedAt: new Date().toISOString() })
                .where(eq(users.id, userId));

            return Result.ok({ secret, qrCode });
        } catch (error: any) {
            return Result.fail(UserError.internal(error.message));
        }
    }
}

import { injectable } from "tsyringe";
import { db } from "@/infrastructure/db";
import { users } from "@/infrastructure/db/schema";
import { Result } from "@/lib/utils/result";
import { UserError } from "../../domain/errors/UserErrors";
import { TwoFactorAuthService } from "../../infrastructure/services/TwoFactorAuthService";
import { eq } from "drizzle-orm";

@injectable()
export class VerifyAndEnable2FAUseCase {
    constructor(
        private tfaService: TwoFactorAuthService
    ) {}

    async execute(userId: string, token: string): Promise<Result<void, UserError>> {
        try {
            const user = await db.query.users.findFirst({ where: eq(users.id, userId) });
            if (!user || !user.twoFactorSecret) {
                return Result.fail(UserError.validation("2FA setup not initiated."));
            }

            const isValid = this.tfaService.verifyToken(token, user.twoFactorSecret);
            if (!isValid) {
                return Result.fail(UserError.unauthorized("Invalid 2FA code."));
            }

            await db.update(users)
                .set({ isTwoFactorEnabled: true, updatedAt: new Date().toISOString() })
                .where(eq(users.id, userId));

            return Result.ok();
        } catch (error: any) {
            return Result.fail(UserError.internal(error.message));
        }
    }
}

import { injectable } from "tsyringe";
import { db } from "@/infrastructure/db";
import { users } from "@/infrastructure/db/schema";
import { Result } from "@/lib/utils/result";
import { UserError } from "../../domain/errors/UserErrors";
import { TwoFactorAuthService } from "../../infrastructure/services/TwoFactorAuthService";
import { eq } from "drizzle-orm";

@injectable()
export class Verify2FATokenUseCase {
    constructor(
        private tfaService: TwoFactorAuthService
    ) {}

    async execute(userId: string, token: string): Promise<Result<boolean, UserError>> {
        try {
            const user = await db.query.users.findFirst({ where: eq(users.id, userId) });
            if (!user || !user.twoFactorSecret || !user.isTwoFactorEnabled) {
                return Result.fail(UserError.validation("2FA is not enabled for this user."));
            }

            const isValid = this.tfaService.verifyToken(token, user.twoFactorSecret);
            return Result.ok(isValid);
        } catch (error: any) {
            return Result.fail(UserError.internal(error.message));
        }
    }
}

